function jsType(v){
  if(v===null) return 'null';
  if(Array.isArray(v)) return 'array';
  if(typeof v==='number') return Number.isInteger(v) ? 'integer' : 'number';
  return typeof v;
}
function jsTypeOk(want, v){
  var t=jsType(v);
  if(want==='number') return t==='number'||t==='integer';
  return want===t;
}
function jsValidate(schema, data, pathPrefix){
  var errs=[], p=pathPrefix||'$';
  if(!schema || typeof schema!=='object') return errs;
  if(schema.type){
    var want=[].concat(schema.type), hit=false;
    for(var i=0;i<want.length;i++) if(jsTypeOk(want[i],data)) hit=true;
    if(!hit){ errs.push({ path:p, msg:'类型应为 '+want.join('|')+'，实际 '+jsType(data) }); return errs; }
  }
  if(schema.enum && schema.enum.indexOf(data)<0)
    errs.push({ path:p, msg:'取值应属于 ['+schema.enum.join(', ')+']' });
  if(typeof data==='number'){
    if(schema.minimum!==undefined && data<schema.minimum) errs.push({ path:p, msg:'应 >= '+schema.minimum });
    if(schema.maximum!==undefined && data>schema.maximum) errs.push({ path:p, msg:'应 <= '+schema.maximum });
  }
  if(typeof data==='string'){
    if(schema.minLength!==undefined && data.length<schema.minLength) errs.push({ path:p, msg:'长度应 >= '+schema.minLength });
    if(schema.maxLength!==undefined && data.length>schema.maxLength) errs.push({ path:p, msg:'长度应 <= '+schema.maxLength });
    if(schema.pattern && !(new RegExp(schema.pattern)).test(data)) errs.push({ path:p, msg:'不匹配 /'+schema.pattern+'/' });
  }
  if(Array.isArray(data)){
    if(schema.minItems!==undefined && data.length<schema.minItems) errs.push({ path:p, msg:'元素数应 >= '+schema.minItems });
    if(schema.maxItems!==undefined && data.length>schema.maxItems) errs.push({ path:p, msg:'元素数应 <= '+schema.maxItems });
    if(schema.items) for(var k=0;k<data.length;k++) errs=errs.concat(jsValidate(schema.items, data[k], p+'['+k+']'));
  }
  if(data && typeof data==='object' && !Array.isArray(data)){
    var req=schema.required||[];
    for(var r=0;r<req.length;r++)
      if(!Object.prototype.hasOwnProperty.call(data, req[r])) errs.push({ path:p+'.'+req[r], msg:'缺少必填字段' });
    var props=schema.properties||{};
    for(var key in props) if(Object.prototype.hasOwnProperty.call(data,key))
      errs=errs.concat(jsValidate(props[key], data[key], p+'.'+key));
    if(schema.additionalProperties===false)
      for(var dk in data) if(!Object.prototype.hasOwnProperty.call(props,dk))
        errs.push({ path:p+'.'+dk, msg:'不允许的额外字段' });
  }
  return errs;
}
function jsInfer(data){
  var t=jsType(data);
  if(t==='array'){
    if(!data.length) return { type:'array' };
    return { type:'array', items: jsInfer(data[0]) };
  }
  if(t==='object'){
    var props={}, req=[];
    for(var k in data){ props[k]=jsInfer(data[k]); req.push(k); }
    return { type:'object', properties:props, required:req };
  }
  return { type:t };
}
function jsRun(schemaText, dataText){
  var schema, data;
  try{ schema=JSON.parse(schemaText); }catch(e){ return { error:'Schema 不是合法 JSON：'+e.message }; }
  try{ data=JSON.parse(dataText); }catch(e){ return { error:'数据不是合法 JSON：'+e.message }; }
  var errs=jsValidate(schema, data, '$');
  return { error:null, valid:errs.length===0, errors:errs };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { jsType:jsType, jsTypeOk:jsTypeOk, jsValidate:jsValidate, jsInfer:jsInfer, jsRun:jsRun };
}
if (typeof window !== 'undefined') {
  window.JsonSchemaForgePure = { jsType:jsType, jsTypeOk:jsTypeOk, jsValidate:jsValidate, jsInfer:jsInfer, jsRun:jsRun };
}
